The DATA wire of the DHT22 module is NOT connected to the Uno. If this code runs for 4.5 seconds, what appears in the serial monitor?

```
#include <DHT.h>
DHT dht(5, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  delay(2000);
  float t = dht.readTemperature();
  if (isnan(t)) Serial.println("HATA");
  else Serial.println(t * 2);
}
```

